const menuButton=document.querySelector('.menu-button');
const navigation=document.querySelector('#navigation');
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open);menuButton.textContent=open?'×':'☰';});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='☰';}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'){navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='☰';}});
document.querySelectorAll('[data-billing]').forEach(button=>button.addEventListener('click',()=>{const annual=button.dataset.billing==='annual';document.querySelectorAll('[data-billing]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-price]').forEach(p=>p.textContent=String(Number(p.dataset.price)*(annual?.8:1)));document.querySelector('#billing-note').textContent=annual?'Yearly equivalent, billed annually: Spark $0 · Orbit $192 · Cosmos $768. Concept pricing; no payments are collected.':'Concept pricing. No payment is collected; launches open a local interactive demo.';}));
const launchDialog=document.querySelector('#launch-dialog');
const form=document.querySelector('#launch-form');
const setup=document.querySelector('#setup-view');
const workspace=document.querySelector('#workspace-view');
let demoAgent=null;
function showSetup(plan){setup.hidden=false;workspace.hidden=true;launchDialog.setAttribute('aria-labelledby','dialog-title');if(plan)form.elements.plan.value=plan;}
document.querySelectorAll('[data-launch]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.plan||!demoAgent)showSetup(button.dataset.plan);launchDialog.showModal();}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
const taskIdeas={'Research & discovery':'Map out three promising directions for my next research project.','Writing & ideas':'Turn a rough idea into an outline for a thoughtful article.','Planning & routines':'Design a calmer week with a practical morning routine.','Coding & building':'Break my next app idea into small, achievable milestones.'};
form.addEventListener('submit',event=>{event.preventDefault();const name=form.elements.agentName.value.trim();if(!name){form.elements.agentName.setCustomValidity('Please give your agent a name.');form.elements.agentName.reportValidity();return;}demoAgent={name,region:form.elements.region.value,plan:form.elements.plan.value,focus:form.elements.focus.value};document.querySelector('#workspace-name').textContent=name;const dl=document.querySelector('#workspace-details');dl.replaceChildren();for(const [label,value]of Object.entries({Region:demoAgent.region,Plan:demoAgent.plan,Focus:demoAgent.focus})){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}document.querySelector('#suggested-task').textContent=taskIdeas[demoAgent.focus];document.querySelector('#task-result').hidden=true;document.querySelector('#sample-task').hidden=false;setup.hidden=true;workspace.hidden=false;launchDialog.setAttribute('aria-labelledby','workspace-name');document.querySelector('#sample-task').focus();});
form.elements.agentName.addEventListener('input',()=>form.elements.agentName.setCustomValidity(''));
document.querySelector('#reset-setup').addEventListener('click',()=>{showSetup();form.elements.agentName.focus();});
document.querySelector('#sample-task').addEventListener('click',()=>{const result=document.querySelector('#task-result');result.textContent='Task preview: define the goal → gather context → outline the next steps. In a connected service, your agent would now begin work. This demo does not run AI requests.';result.hidden=false;document.querySelector('#sample-task').hidden=true;});
const infoDialog=document.querySelector('#info-dialog');
document.querySelectorAll('[data-info]').forEach(button=>button.addEventListener('click',()=>{const privacy=button.dataset.info==='privacy';document.querySelector('#info-title').textContent=privacy?'Your space, respected.':'A few inspirations.';document.querySelector('#info-content').innerHTML=privacy?'<p>This concept website does not create accounts, collect payments, or send your demo configuration to a server. Demo state exists only in this page and clears when you reload.</p><p>Google Fonts supplies the typefaces and may receive ordinary connection information. External documentation links open third-party websites with their own privacy practices.</p>':'<p>Atlas Cloud is an independent design concept, inspired by the electric-blue palette and editorial structure of <a href="https://portal.nousresearch.com/cloud" target="_blank" rel="noopener noreferrer">Hermes Cloud by Nous Research</a>.</p><p>Additional visual research: <a href="https://github.com/opencolin/hermes-garden" target="_blank" rel="noopener noreferrer">Hermes Garden</a>, a study of scientific-instrument aesthetics. All Atlas page code, identity, and copy are original. The observatory artwork was generated specifically for this project.</p><p>Typefaces: DM Sans and IBM Plex Mono via Google Fonts. Atlas is not affiliated with Nous Research.</p>';infoDialog.showModal();}));
